// EDIT THESE before you run. Every step below reads them.
return [{ json: {
  sender_name: 'Your Name',
  sender_role: 'Partnerships',
  sender_company: 'Your Company',
  company_pitch: 'Your Company is a [what you do] based in [city]. It looks for partners that bring [market access, credits, capital, customers or talent].',
  contacts_per_company: 2,                         // people per company in the Outreach sheet
  default_location: 'United Arab Emirates',        // used when a target's contact_location is blank
  default_titles: 'Partnerships; Business Development; Startups; Ecosystem; Alliances',
  hunter_enrich: true                              // true = also check each person's location/phone with Hunter (0.2 credits each)
}}];

// Only process targets that don't have a brief yet. To redo one, delete its Briefs row.
const done = new Set($input.all().map(i => String(i.json.name || '').trim().toLowerCase()).filter(Boolean));
return $('Read Targets').all()
  .filter(i => String(i.json.name || '').trim() && !done.has(String(i.json.name).trim().toLowerCase()))
  .map(i => ({ json: i.json }));

// Website text + the target's settings, with defaults filled in
const html = String($input.first().json.data || '');
const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&amp;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 8000);
const p = $('Loop Over Items').first().json;
const cfg = $('Config').first().json;
let domain = String(p.domain || '').trim();
if (!domain && p.website) { try { domain = new URL(p.website).hostname.replace(/^www\./, ''); } catch (e) {} }
return [{ json: {
  name: p.name,
  website: p.website || '',
  domain,
  linkedin_company: p.linkedin_company || p.name,
  type: p.type || '',
  contact_location: p.contact_location || cfg.default_location,
  contact_titles: p.contact_titles || cfg.default_titles,
  text: text || 'No website text could be fetched. Use general knowledge of this organisation.'
}}];

const raw = String($input.first().json.text || '');
let b = {};
try { const m = raw.match(/\{[\s\S]*\}/); b = JSON.parse(m ? m[0] : raw); }
catch (e) { b = { summary: 'Could not parse AI output: ' + raw.slice(0, 300) }; }
const p = $('Clean Text').first().json;
return [{ json: {
  name: p.name, website: p.website, type: p.type, contact_location: p.contact_location,
  summary: b.summary || '', what_they_want: b.what_they_want || '', what_we_get: b.what_we_get || '',
  trade: b.trade || '', priority: b.priority || '', created: new Date().toISOString().slice(0, 10)
}}];

// Three Google searches via Serper:
//  1) LinkedIn profiles: company + role keywords + location
//  2) LinkedIn profiles: company + location + broad partnership words (catches different titles)
//  3) Google Maps: the company's office in that location (office phone)
const t = $('Clean Text').first().json;
const GL = { 'united arab emirates': 'ae', 'uae': 'ae', 'dubai': 'ae', 'abu dhabi': 'ae', 'saudi arabia': 'sa',
  'ksa': 'sa', 'riyadh': 'sa', 'qatar': 'qa', 'doha': 'qa', 'bahrain': 'bh', 'kuwait': 'kw', 'oman': 'om',
  'egypt': 'eg', 'türkiye': 'tr', 'turkey': 'tr', 'istanbul': 'tr', 'united kingdom': 'gb', 'uk': 'gb',
  'london': 'gb', 'united states': 'us', 'usa': 'us', 'pakistan': 'pk', 'netherlands': 'nl', 'germany': 'de',
  'ireland': 'ie', 'france': 'fr', 'india': 'in', 'singapore': 'sg' };
const loc = String(t.contact_location).trim();
const gl = GL[loc.toLowerCase()] || 'us';
const company = String(t.linkedin_company).trim();
const titles = String(t.contact_titles).split(/[;|]/).map(s => s.trim()).filter(Boolean);
const titleOr = titles.map(x => '"' + x + '"').join(' OR ');
return [
  { json: { kind: 'people', endpoint: 'search', gl,
    q: `site:linkedin.com/in "${company}" (${titleOr}) "${loc}"` } },
  { json: { kind: 'people', endpoint: 'search', gl,
    q: `site:linkedin.com/in "${company}" "${loc}" (partnerships OR partner OR "business development" OR startups OR ecosystem OR alliances)` } },
  { json: { kind: 'office', endpoint: 'places', gl, q: `${company} office ${loc}` } }
];

// Merge LinkedIn results (deduplicated) and take the office phone from the Maps result
const reqs = $('Build Searches').all();
const t = $('Clean Text').first().json;
const LOCAL = {
  ae: ['united arab emirates', 'uae', 'dubai', 'abu dhabi', 'sharjah', 'ajman', 'ras al khaimah'],
  sa: ['saudi arabia', 'riyadh', 'jeddah', 'dammam', 'khobar'], qa: ['qatar', 'doha', 'education city'],
  bh: ['bahrain', 'manama'], kw: ['kuwait'], om: ['oman', 'muscat'], eg: ['egypt', 'cairo'],
  tr: ['türkiye', 'turkey', 'istanbul', 'ankara', 'izmir', 'i̇stanbul'],
  gb: ['united kingdom', 'england', 'scotland', 'london', 'manchester', 'cheltenham'],
  us: ['united states', 'usa', ', ny', ', ca'], pk: ['pakistan', 'karachi', 'lahore', 'islamabad'],
  nl: ['netherlands', 'amsterdam'], de: ['germany', 'berlin', 'munich'], ie: ['ireland', 'dublin'],
  fr: ['france', 'paris'], in: ['india'], sg: ['singapore']
};
const seen = new Set();
const candidates = [];
let office = {};
$input.all().forEach((r, i) => {
  const kind = reqs[i] && reqs[i].json.kind;
  const d = r.json || {};
  if (kind === 'people') {
    (d.organic || []).forEach(o => {
      const link = String(o.link || '').split('?')[0];
      if (!/linkedin\.com\/in\//i.test(link) || seen.has(link)) return;
      seen.add(link);
      candidates.push({ n: candidates.length + 1, title: o.title || '', snippet: o.snippet || '', link });
    });
  } else if (kind === 'office') {
    // Only accept an office that is actually in the target location
    const places = d.places || [];
    const word = String(t.linkedin_company).toLowerCase().split(' ')[0];
    const gl = (reqs[i] && reqs[i].json.gl) || '';
    const here = (LOCAL[gl] || []).concat(String(t.contact_location).toLowerCase());
    const inLoc = x => here.some(n => n && String(x.address || '').toLowerCase().includes(n));
    const p = places.find(x => inLoc(x) && String(x.title || '').toLowerCase().includes(word)) || places.find(inLoc) || {};
    office = { office_phone: p.phoneNumber || p.phone_number || p.phone || '', office_address: p.address || '' };
  }
});
const top = candidates.slice(0, 20);
const handleOf = u => { const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : ''; };
const links = {};
top.forEach(c => { const h = handleOf(c.link); if (h) links[h] = 'https://www.linkedin.com/in/' + h; });
const list = top.map(c => `[${c.n}] ${c.title}\n${c.snippet}\n${c.link}`).join('\n\n');
const gl = ($('Build Searches').first().json || {}).gl || '';
return [{ json: { count: candidates.length, list: list || 'NO RESULTS', links, gl, ...office } }];

// One item per chosen person, or one 'skip' item so the loop moves on
const raw = String($input.first().json.text || '');
const t = $('Clean Text').first().json;
const brief = $('Parse Brief').first().json;
const found = $('Collect Results').first().json;
const cfg = $('Config').first().json;
let people = [];
try { const m = raw.replace(/```json/g, '').replace(/```/g, '').trim().match(/\[[\s\S]*\]/); people = m ? JSON.parse(m[0]) : []; }
catch (e) { people = []; }
// Accept a person only if their LinkedIn URL really appeared in the Google results
const handleOf = u => { const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : ''; };
const links = found.links || {};
people = people
  .map(p => ({ ...p, _h: handleOf(p && p.linkedin_url) }))
  .filter(p => p && p.first_name && p._h && links[p._h])
  .map(p => ({ ...p, linkedin_url: links[p._h] }))
  .slice(0, Number(cfg.contacts_per_company || 2));
if (!people.length) {
  return [{ json: { skip: true, company: t.name,
    reason: found.count ? 'No current employee in ' + t.contact_location + ' among search results' : 'No LinkedIn results' } }];
}
return people.map(p => ({ json: {
  skip: false,
  company: t.name, domain: t.domain, contact_location: t.contact_location,
  first_name: String(p.first_name).trim(), last_name: String(p.last_name || '').trim(),
  title: p.title || '', location: p.location || '', linkedin_url: p.linkedin_url, match_reason: p.reason || '', gl: found.gl || '',
  office_phone: found.office_phone || '', office_address: found.office_address || '',
  summary: brief.summary, what_they_want: brief.what_they_want, trade: brief.trade
}}));

// Combine the chosen person + Hunter Email Finder + Hunter Enrichment,
// and check that Hunter's data describes the SAME person we picked from Google.
const people = $('Has Contact?').all(0);
const finder = $('Find Email (Hunter)').all();
const handleOf = u => { const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : String(u || '').toLowerCase().replace(/\/+$/, ''); };
// LinkedIn sometimes appends an ID ("nora-m-alsarhan-92a07339"); ignore it when comparing
const coreOf = h => String(h || '').replace(/-[0-9a-f]{6,}$/i, '').replace(/-\d+$/, '');
const ALIASES = {
  ae: ['united arab emirates', 'uae', 'dubai', 'abu dhabi', 'sharjah', 'ajman', 'ras al khaimah'],
  sa: ['saudi arabia', 'saudi', 'ksa', 'riyadh', 'jeddah', 'dammam', 'khobar'],
  qa: ['qatar', 'doha'], bh: ['bahrain', 'manama'], kw: ['kuwait'], om: ['oman', 'muscat'], eg: ['egypt', 'cairo'],
  tr: ['türkiye', 'turkiye', 'turkey', 'istanbul', 'ankara', 'izmir'],
  gb: ['united kingdom', 'uk', 'england', 'scotland', 'london', 'manchester'],
  us: ['united states', 'usa', 'u.s.'], pk: ['pakistan', 'karachi', 'lahore', 'islamabad'],
  nl: ['netherlands', 'amsterdam'], de: ['germany', 'berlin', 'munich'], ie: ['ireland', 'dublin'], sg: ['singapore']
};
const STOP = new Set(['and', 'of', 'the', 'at', 'for', 'in', '&', '-', 'manager', 'senior', 'lead']);
const words = t => String(t || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2 && !STOP.has(w));

return $input.all().map((r, i) => {
  const p = (people[i] && people[i].json) || {};
  const f = (finder[i] && finder[i].json && finder[i].json.data) || {};
  const e = (r.json && r.json.data) || {};
  const emp = e.employment || {};
  const hunterLoc = e.location || [e.geo && e.geo.city, e.geo && e.geo.country].filter(Boolean).join(', ');
  const hunterLi = f.linkedin_url || (e.linkedin && e.linkedin.handle) || '';
  const hunterTitle = f.position || emp.title || '';

  // 1. LinkedIn: same profile?
  const gH = handleOf(p.linkedin_url), hH = hunterLi ? handleOf(hunterLi) : '';
  const liMatch = hH ? (coreOf(gH) === coreOf(hH)) : null;
  // 2. Location: Hunter's location inside the target location?
  const gl = String(p.gl || '').toLowerCase();
  const cc = String((e.geo && e.geo.countryCode) || '').toLowerCase();
  const names = (ALIASES[gl] || []).concat(String(p.contact_location || '').toLowerCase());
  const locMatch = hunterLoc ? ((cc && gl && cc === gl) || names.some(n => n && hunterLoc.toLowerCase().includes(n))) : null;
  // 3. Title: do the two titles share a meaningful word?
  const gw = new Set(words(p.title));
  const titleMatch = hunterTitle ? words(hunterTitle).some(w => gw.has(w)) : null;

  let check;
  if (!f.email) check = 'No email found';
  else if (liMatch === false) check = 'Check: Hunter links this email to a different LinkedIn (' + hunterLi + ')';
  else if (locMatch === false) check = 'Check: Hunter shows ' + hunterLoc + ', not ' + p.contact_location;
  else if (liMatch && locMatch) check = 'Verified: LinkedIn + location match';
  else if (liMatch) check = 'Verified: LinkedIn match';
  else if (locMatch) check = 'Likely: location matches' + (titleMatch ? ' + title' : '');
  else if (titleMatch) check = 'Likely: title matches';
  else if (titleMatch === false) check = 'Check: Hunter title is "' + hunterTitle + '"';
  else check = 'Unverified: no Hunter data to compare';

  return { json: {
    ...p,
    contact_name: [p.first_name, p.last_name].filter(Boolean).join(' '),
    title: p.title || hunterTitle,
    location: p.location || hunterLoc,
    hunter_location: hunterLoc,
    linkedin_url: p.linkedin_url || (hunterLi ? (hunterLi.startsWith('http') ? hunterLi : 'https://www.linkedin.com/in/' + hunterLi) : ''),
    email: f.email || '',
    email_status: (f.verification && f.verification.status) || (f.score ? f.score + '% confidence' : ''),
    contact_check: check,
    direct_phone: f.phone_number || e.phone || ''
  }};
});

