// One row per contact for the Outreach sheet
const contacts = $('Merge Contact').all();
return $input.all().map((o, i) => {
  const c = (contacts[i] && contacts[i].json) || {};
  const raw = String(o.json.text || '');
  let m = {};
  try { const j = raw.match(/\{[\s\S]*\}/); m = JSON.parse(j ? j[0] : raw); } catch (e) { m = { email_body: raw }; }
  return { json: {
    company: c.company || '', contact_name: c.contact_name || '', title: c.title || '',
    location: c.location || '', hunter_location: c.hunter_location || '', linkedin_url: c.linkedin_url || '',
    email: c.email || '', email_status: c.email_status || '', contact_check: c.contact_check || '',
    direct_phone: c.direct_phone || '', office_phone: c.office_phone || '', office_address: c.office_address || '',
    email_subject: m.email_subject || '', email_body: m.email_body || '',
    linkedin_connection_note: m.linkedin_connection_note || '', linkedin_message: m.linkedin_message || '',
    match_reason: c.match_reason || '', status: 'Draft', created: new Date().toISOString().slice(0, 10)
  }};
});
